SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0870000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 87, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "87", "printedPageNumber": 87, "pdfPageNumber": 470, "sequenceIndex": 77, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0870100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith V", "sourceIdentifier": "V", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0870000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (c)—Quotations from Ahadith", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}, {"id": "f0870100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "is scared of a Muslim so long as he is mindful of his salaat; but no sooner he neglects the salaat than Satan descends on him and becomes hopeful of leading him astray, and then he can easily be lured to commit more serious wrongs and major sins. This is exactly what is meant by Almighty Allah when He says,", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}, {"id": "f0870200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "إِنَّ الصَّلَاةَ تَنْهَىٰ عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}, {"id": "f0870300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Lo! salaat preserveth from lewdness and inequity\" (XXIX: 45)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}, {"id": "f0870400-0000-4000-8000-000000000001", "structuralNodeId": "b0870100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith V", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}, {"id": "f0870500-0000-4000-8000-000000000001", "structuralNodeId": "b0870100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن عبد الله بن أبي قتادة رضي الله عنه قال رسول الله ﷺ أسوأ الناس سرقة الذي يسرق من صلاته قالوا يا رسول الله كيف يسرق من صلاته قال لا يتم ركوعها ولا سجودها رواه أحمد", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}, {"id": "f0870600-0000-4000-8000-000000000001", "structuralNodeId": "b0870100-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abdullah bin Abu Qataadah (Radhiyallaho anho) narrates, \"The Holy Prophet (Sallallaho alaihe wasallam) once said, ''The worst thief is one who steals from his salaat.'' The companions inquired, ''How can one steal from his salaat? O, Prophet of Allah!'' He replied, ''When one does not do his ruku and sajdah properly.''\n\nThere are many other Ahaadith conveying the same meaning. Stealing is a very disgraceful act and a thief is despised by everybody. What about a person who is declared ''the worst thief'', by no less a person than the Prophet himself?\n\nHadhrat Abu Darda (Radhiyallaho anho) narrates, \"Once the Prophet (Sallallaho alaihe wasallam) looked up towards the sky and said, ''The knowledge of Deen is soon to be taken away from this world.'' Ziyaad (Radhiyallaho anho), who was also present there inquired, ''How can the knowledge of Deen be taken away, O, Prophet of Allah (Sallallaho alaihe wasallam), when we are teaching the Qur''an to our children and this process will continue in our posterity?'' The Prophet (Sallallaho alaihe wasallam) said to him, ''Ziyaad! I always took you to be an intelligent person. Don''t you see that the Jews and the Christians are also teaching their Bibles to their children? Has this prevented", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}]}'::jsonb);